// Decodifica ad_ref con formato: VENDOR-CATEGORY-MODEL-YEAR[-PRICE]
// Ejemplos:
//   CURT-HITCH-SYSTEM-199           -> vendor=CURT, category=HITCH-SYSTEM, price=199
//   THULE-BIKE-RACK-HILUX-2024      -> vendor=THULE, category=BIKE-RACK, vehicle_model=HILUX, year=2024
//   WEATHERTECH-FLOORLINER-CRV-2023 -> vendor=WEATHERTECH, category=FLOORLINER, vehicle_model=CRV, year=2023
const raw = $input.first().json || {};

// Detectar si los parámetros están dentro de un objeto 'query'
const data = (raw.query && typeof raw.query === 'object' && !Array.isArray(raw.query)) ? raw.query : raw;
const ref = (data.ad_ref || data.ref || raw.ad_ref || raw.ref || '').trim();

if (!ref) {
  return [{ json: { decoded: false, message: 'ad_ref vacío' } }];
}

const parts = ref.split('-').map(p => p.trim()).filter(Boolean);
if (parts.length < 2) {
  return [{ json: { decoded: false, ref, message: 'formato no reconocido' } }];
}

const vendor = parts[0];
const KNOWN_CATS = ['HITCH-SYSTEM','HITCH','BIKE-RACK','ROOF-RACK','CARGO-CARRIER','FLOORLINER','MUD-FLAP','LUGGAGE','CARGO-BAG'];

// Detecta categoría compuesta tomando los siguientes 1-2 tokens
let category = null;
let rest = parts.slice(1);
for (const cat of KNOWN_CATS) {
  const catTokens = cat.split('-');
  const head = rest.slice(0, catTokens.length).join('-').toUpperCase();
  if (head === cat) { category = cat; rest = rest.slice(catTokens.length); break; }
}
if (!category) { category = rest.shift(); }

// Año: token numérico 19xx-20xx
let year = null;
for (let i = rest.length - 1; i >= 0; i--) {
  const n = parseInt(rest[i], 10);
  if (Number.isInteger(n) && n >= 1980 && n <= 2099) { year = n; rest.splice(i,1); break; }
}

// Precio: token numérico ≤ 9999 sin coincidir con año
let price = null;
for (let i = rest.length - 1; i >= 0; i--) {
  const n = parseInt(rest[i], 10);
  if (Number.isInteger(n) && n > 0 && n < 10000) { price = n; rest.splice(i,1); break; }
}

// Lo que quede es modelo de vehículo
const vehicle_model = rest.length ? rest.join(' ') : null;

return [{ json: {
  decoded: true,
  ref,
  vendor,
  category,
  vehicle_model,
  year,
  price,
  hint: `Anuncio de ${vendor} (${category})${vehicle_model ? ' para ' + vehicle_model : ''}${year ? ' ' + year : ''}${price ? ', precio referencial $' + price : ''}`
} }];
